import React, { useState, useEffect } from 'react';
import { MatrixInput } from './MatrixInput';
import { MatrixTextInput } from './MatrixTextInput';
import { FileUpload } from './FileUpload';
import { ResultsDisplay } from './ResultsDisplay';
import { IterationTable } from './IterationTable';
import { Alert } from '../common/Alert';
import { Loader } from '../common/Loader';
import { lab1Api } from '../../services/api';
import { SolutionResponse, FileData } from '../../types';
import { Play, FileText, Keyboard, Grid3x3, Settings2 } from 'lucide-react';
import toast from 'react-hot-toast';

type InputMode = 'manual' | 'text' | 'file';

export const SLAUPage: React.FC = () => {
    const [n, setN] = useState<number>(3);
    const [inputMode, setInputMode] = useState<InputMode>('manual');
    const [matrix, setMatrix] = useState<number[][]>(
        Array(3).fill(0).map(() => Array(3).fill(0))
    );
    const [vector, setVector] = useState<number[]>(Array(3).fill(0));
    const [epsilon, setEpsilon] = useState<number>(0.0001);
    const [maxIterations, setMaxIterations] = useState<number>(100);
    const [loading, setLoading] = useState<boolean>(false);
    const [result, setResult] = useState<SolutionResponse | null>(null);

    useEffect(() => {
        if (inputMode === 'manual' || inputMode === 'text') {
            setMatrix(Array(n).fill(0).map(() => Array(n).fill(0)));
            setVector(Array(n).fill(0));
        }
        setResult(null);
    }, [n, inputMode]);

    const handleNChange = (newN: number) => {
        const val = Math.min(Math.max(newN, 1), 20);
        setN(val);
    };

    const handleFileData = (data: FileData) => {
        setN(data.matrix.length);
        setMatrix(data.matrix);
        setVector(data.vector);
        setResult(null);
        toast.success('Матрица загружена');
    };

    const handleSolve = async () => {
        setLoading(true);
        try {
            const response = await lab1Api.solve({
                matrix,
                vector,
                params: { epsilon, maxIterations }
            });

            setResult(response.data);
            if (response.data.status === 'success') {
                toast.success('Решение получено');
                // Скролл к результатам для удобства
                document.getElementById('results-anchor')?.scrollIntoView({ behavior: 'smooth' });
            } else {
                toast.error(response.data.message);
            }
        } catch (error: any) {
            toast.error(error.message || 'Ошибка сервера');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container mx-auto px-4 py-8 max-w-6xl">
            {/* Header */}
            <div className="mb-6 bg-white rounded-xl shadow-sm border p-6 flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Вычислительная математика</h1>
                    <p className="text-gray-500">Лабораторная работа №1: Метод Гаусса-Зейделя</p>
                </div>
                <div className="text-right hidden sm:block">
                    <p className="font-semibold text-gray-800">Ясаков А. А. | P3213</p>
                    <p className="text-sm text-gray-500">Вариант №20</p>
                </div>
            </div>

            {/* Input Section - FULL WIDTH */}
            <div className="bg-white rounded-xl shadow-md border overflow-hidden mb-8">
                <div className="p-6 border-b bg-gray-50 flex flex-wrap items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <Settings2 size={18} className="text-gray-400" />
                            <span className="font-semibold">Параметры:</span>
                        </div>
                        <div className="flex items-center gap-3 bg-white px-3 py-1.5 rounded-lg border">
                            <label className="text-sm text-gray-500 font-medium uppercase">n:</label>
                            <input
                                type="number"
                                value={n}
                                onChange={(e) => handleNChange(parseInt(e.target.value) || 1)}
                                className="w-12 text-center font-bold focus:outline-none"
                            />
                        </div>
                        <div className="flex items-center gap-3 bg-white px-3 py-1.5 rounded-lg border">
                            <label className="text-sm text-gray-500 font-medium uppercase">ε:</label>
                            <input
                                type="number"
                                step="0.0001"
                                value={epsilon}
                                onChange={(e) => setEpsilon(parseFloat(e.target.value))}
                                className="w-24 text-center focus:outline-none"
                            />
                        </div>
                    </div>

                    <div className="flex bg-white p-1 rounded-xl border">
                        <button
                            onClick={() => setInputMode('manual')}
                            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg transition-all ${inputMode === 'manual' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
                        >
                            <Grid3x3 size={16} /> <span className="text-sm font-medium">Таблица</span>
                        </button>
                        <button
                            onClick={() => setInputMode('text')}
                            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg transition-all ${inputMode === 'text' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
                        >
                            <FileText size={16} /> <span className="text-sm font-medium">Текст</span>
                        </button>
                        <button
                            onClick={() => setInputMode('file')}
                            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg transition-all ${inputMode === 'file' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
                        >
                            <Keyboard size={16} /> <span className="text-sm font-medium">Файл</span>
                        </button>
                    </div>
                </div>

                <div className="p-6">
                    {/* Area for Matrix Input */}
                    <div className="overflow-x-auto pb-4">
                        {inputMode === 'manual' && <MatrixInput n={n} matrix={matrix} vector={vector} onChange={(m, v) => { setMatrix(m); setVector(v); }} />}
                        {inputMode === 'text' && <MatrixTextInput n={n} matrix={matrix} vector={vector} onChange={(m, v) => { setMatrix(m); setVector(v); }} />}
                        {inputMode === 'file' && <FileUpload onDataLoaded={handleFileData} />}
                    </div>

                    <button
                        onClick={handleSolve}
                        disabled={loading}
                        className="mt-6 w-full py-4 bg-green-600 hover:bg-green-700 text-white rounded-xl font-bold text-lg shadow-lg shadow-green-100 transition-all flex items-center justify-center gap-3 disabled:bg-gray-300"
                    >
                        {loading ? <Loader /> : <><Play fill="currentColor" size={20} /> Вычислить решение</>}
                    </button>
                </div>
            </div>

            {/* Results Section - FULL WIDTH */}
            <div id="results-anchor" className="space-y-6">
                {result ? (
                    <div className="bg-white rounded-xl shadow-md border p-8">
                        <h2 className="text-2xl font-bold text-gray-900 mb-8 border-b pb-4">Отчет по итерациям</h2>

                        {result.status === 'error' ? (
                            <Alert type="error" message={result.message} />
                        ) : (
                            <div className="space-y-12">
                                <ResultsDisplay result={result} />

                                {result.iterationHistory && (
                                    <div className="space-y-4">
                                        <h3 className="text-xl font-bold text-gray-800">Таблица сходимости метода</h3>
                                        <IterationTable history={result.iterationHistory} solution={result.solution} />
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                ) : (
                    <div className="py-20 text-center border-2 border-dashed rounded-2xl text-gray-400">
                        <p className="text-xl">Система готова к расчету</p>
                        <p className="text-sm">Заполните матрицу коэффициентов и нажмите кнопку выше</p>
                    </div>
                )}
            </div>
        </div>
    );
};
